  const statusText=k=>({posted:t('已完成','Completed'),completed:t('已完成','Completed'),pending:t('待确认','Pending'),approved:t('已通过 · 待发货','Approved · Ready'),shipped:t('在途 · 待收货','In transit'),rejected:t('已驳回','Rejected'),refunded:t('已退款 / 冲销','Refunded / Reversed'),received:t('已入库','Received'),active:t('启用','Active'),inactive:t('停用','Inactive')})[k]||k;
