  function normalize(){if(!u())return;const stores=allowed();if(!stores.some(s=>s.id===state.scope)&&!(state.scope==='all'&&u().role!=='manager'))state.scope=u().role==='manager'?stores[0].id:'all';if(u().role==='manager'&&['users','data','suppliers','finance'].includes(state.tab)){state.tab=state.page==='inventory'?'stock':'profiles';}}
  function renderLogin(message=''){$('#appShell').hidden=true;$('#loginShell').hidden=false;$('#loginShell').innerHTML=`<div class="login-frame"><div class="login-art">${logo()}<div class="eyebrow">A LITTLE MORE STYLE. A LOT MORE CLARITY.</div><h1>${t('每一间门店，<br>都值得被看见。','Every store.<br>A clearer perspective.')}</h1><p>${t('从一笔销售，到每一次补货。让经营数据与门店日常，在同一个地方有序发生。','From a single sale to the next replenishment. Bring your numbers, merchandise and people together.')}</p><div class="login-illustration"><svg viewBox="0 0 260 240" fill="none" aria-hidden="true"><circle cx="130" cy="130" r="100" stroke="#ffffff12"/><circle cx="130" cy="130" r="78" stroke="#ffffff10"/><path d="M83 52 130 66l47-14 37 58-24 19-18-30 14 104H73L88 99l-18 30-24-19z" fill="#bd96a5"/><path d="m84 52 45 43 47-43M129 95v104M89 139h30" stroke="#dfc4ca" stroke-width="3"/><circle cx="138" cy="114" r="2" fill="#e4cfd2"/><circle cx="138" cy="133" r="2" fill="#e4cfd2"/><circle cx="138" cy="153" r="2" fill="#e4cfd2"/></svg><div class="login-metric"><small>${t('两间店，一个视角','Two stores, one perspective')}</small><strong>Connected.</strong></div><div class="login-metric second"><small>${t('库存 · 销售 · 会员','Stock · Sales · Members')}</small><strong>All in sync ↗</strong></div></div><div class="login-points"><span>01 / ${t('经营洞察','INSIGHTS')}</span><span>02 / ${t('库存协同','INVENTORY')}</span><span>03 / ${t('双语工作台','BILINGUAL')}</span></div></div><div class="login-panel">${language()}<h2>${t('欢迎回来','Welcome back')}</h2><p>${t('登录你的门店经营工作台','Sign in to your retail workspace')}</p><form id="loginForm" class="login-form"><label class="field"><span>${t('账号','Username')}</span><input id="usernameInput" name="username" autocomplete="username" required placeholder="admin.lf"></label><label class="field"><span>${t('密码','Password')}</span><input id="passwordInput" name="password" type="password" autocomplete="current-password" required placeholder="${t('请输入演示密码','Demo password')}"></label><div id="loginError" class="form-error" ${message?'':'hidden'}>${e(message)}</div><button class="btn" id="loginSubmit" type="submit">${t('登录工作台','Sign in')} ${icon('arrow')}</button></form><div class="demo-label">${t('选择一个演示身份','CHOOSE A DEMO ACCOUNT')}</div><div class="account-list">${[['lin.director','Demo@2026',t('运营总监 · 全部门店','Director · All stores')],['zhou.store','Store#2026',t('店铺 B 店长 · 本店经营','Store B manager · Assigned store')],['admin.lf','Admin#2026',t('系统管理员 · 全部权限','Administrator · Full access')]].map(a=>`<div class="account-item"><div><strong>${a[0]}</strong><small>${a[2]} · <code>${a[1]}</code></small></div><button type="button" data-action="fill-account" data-id="${a[0]}" data-password="${e(a[1])}">${t('填入','Use')} →</button></div>`).join('')}</div><p class="login-foot">LADY FASHION / RETAIL WORKSPACE · V2.0</p></div></div>`;}
  function renderShell(){const menu=[['overview',t('概览','Overview')],['sales',t('销售分析','Sales')],['inventory',t('出入库','Inventory')],['stores',t('店铺管理','Stores')]];$('#sidebar').innerHTML=`${logo()}<div><div class="nav-caption">${t('经营工作台','WORKSPACE')}</div><nav class="nav-menu" aria-label="${t('主导航','Main navigation')}">${menu.map(([id,label])=>`<button class="nav-item ${state.page===id?'active':''}" data-action="navigate" data-id="${id}" aria-current="${state.page===id?'page':'false'}">${icon(id)}<span>${label}</span></button>`).join('')}</nav></div><div class="sidebar-bottom"><div class="side-note"><strong>${t('让每一次经营更从容','A calmer way to manage.')}</strong>${t('销售与库存，同步向前。','Your sales and stock, in step.')}</div><div class="side-user"><div class="avatar">${e(name(u()).slice(0,1))}</div><div><strong>${e(name(u()))}</strong><small>${e(roleText(u().role))}</small></div></div></div>`;
    const notices=getNotices();$('#topbar').innerHTML=`<div class="store-selector"><label for="storeSelect">${t('经营范围','STORE SCOPE')}</label><select id="storeSelect" aria-label="${t('店铺选择','Store scope')}">${u().role!=='manager'?`<option value="all">${t('所有店铺','All stores')} · 02</option>`:''}${allowed().map(s=>`<option value="${s.id}">${e(storeLabel(s.id))}</option>`).join('')}</select></div><div class="top-actions"><button type="button" class="search-button" data-action="search">${icon('search')}<span>${t('搜索商品、单据…','Search products, records…')}</span><kbd>/</kbd></button>${language()}<span class="top-divider"></span><button type="button" class="icon-button" data-action="notifications" aria-label="${t('通知','Notifications')}">${icon('bell')}${notices.some(x=>!isRead(x.id))?'<i class="badge-dot"></i>':''}</button><button type="button" class="icon-button" data-action="help" aria-label="${t('帮助','Help')}">${icon('help')}</button><button id="logoutButton" type="button" class="icon-button" data-action="logout" aria-label="${t('退出登录','Sign out')}">${icon('logout')}</button></div>`;$('#storeSelect').value=state.scope;
    $('#footer').innerHTML=`<span>LADY FASHION <span>© ${new Date().getFullYear()}</span> · ${t('门店经营中心','Retail workspace')}</span><span><i class="save-dot"></i>${t('已保存','Saved')} · ${e(new Date(F.db.updatedAt||F.db.createdAt).toLocaleTimeString(state.lang==='zh'?'zh-CN':'en-US',{hour:'2-digit',minute:'2-digit'}))}</span>`;
  }
  function heading(title,sub,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${state.page==='overview'?'THE RETAIL EDIT':state.page==='sales'?'SALES & RELATIONSHIPS':state.page==='inventory'?'INVENTORY & OPERATIONS':'STORES & ORGANIZATION'}</div><h1>${title}</h1><p class="subtext">${sub}</p></div><div class="heading-actions"><input id="monthSelect" aria-label="${t('统计月份','Reporting month')}" class="date-control" type="month" value="${e(state.month)}" max="${F.monthOf()}">${actions}</div></div>`;}
  function tabs(items,defaultTab){if(!items.some(x=>x[0]===state.tab))state.tab=defaultTab;return `<div class="tabbar" role="tablist" aria-label="${t('功能分区','Sections')}">${items.map(([id,label])=>`<button type="button" role="tab" aria-selected="${id===state.tab}" class="${id===state.tab?'active':''}" data-action="tab" data-id="${id}">${label}</button>`).join('')}</div>`;}
  function empty(text=t('当前范围暂无记录','No records in this scope')){return `<div class="empty">${icon('file')}${text}</div>`;}
  function table(headers,rows){return rows.length?`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty();}
  function paginated(headers,rows,key='main'){const pageSize=10,max=Math.max(1,Math.ceil(rows.length/pageSize));state.pageIndex=Math.min(state.pageIndex,max-1);return table(headers,rows.slice(state.pageIndex*pageSize,(state.pageIndex+1)*pageSize))+`<div class="pagination"><span>${t('共','Total')} ${rows.length} ${t('条','records')} · ${state.pageIndex+1} / ${max}</span><div>${btn('‹','page',String(Math.max(0,state.pageIndex-1)),'secondary small')}${btn('›','page',String(Math.min(max-1,state.pageIndex+1)),'secondary small')}</div></div>`;}
  function productCell(p){return `<div class="cell-title">${garment(p)}<div><strong>${e(name(p))}</strong><small>${e(p.sku)} · ${e(state.lang==='zh'?p.color:p.colorEn)} / ${e(p.size)}</small></div></div>`;}
  function panel(title,sub,body,action=''){return `<section class="panel"><div class="panel-header"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>${body}</section>`;}
  function lineChart(){const points=[],current=[],previous=[],year=[],labels=[];const [sy,sm]=state.month.split('-').map(Number);for(let i=-5;i<=0;i++){const dt=new Date(sy,sm-1+i,1),month=F.localDate(dt).slice(0,7),period=F.periods(month);labels.push(month.slice(2).replace('-','.'));current.push(F.metrics(F.db,ids(),period.current).amount);previous.push(F.metrics(F.db,ids(),period.previous).amount);year.push(F.metrics(F.db,ids(),period.year).amount);}
    const W=660,H=235,pad={l:50,r:20,t:22,b:35},max=Math.max(...current,...previous,...year,100),maxY=Math.ceil(max/1000000)*1000000||1000000,x=i=>pad.l+i*(W-pad.l-pad.r)/5,y=v=>H-pad.b-(H-pad.t-pad.b)*v/maxY;
    let svg=`<svg class="chart-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="${t('最近六个月销售趋势，含上月和去年同期对比','Six-month sales with previous month and year comparisons')}"><title>${t('所有点均由销售账本统计','Every point is derived from the sales ledger')}</title>`;for(let i=0;i<=4;i++){const value=maxY*i/4,yy=y(value);svg+=`<line class="grid" x1="${pad.l}" x2="${W-pad.r}" y1="${yy}" y2="${yy}"/><text x="${pad.l-12}" y="${yy+4}" text-anchor="end">${Math.round(value/100000)}k</text>`;}
    svg+=`<path d="${current.map((v,i)=>`${i?'L':'M'}${x(i)},${y(v)}`).join(' ')} L${x(5)},${y(0)} L${x(0)},${y(0)} Z" fill="#f4eaee"/>`;
    [[year,'#c7bba8',true],[previous,'#c8a2b3',true],[current,'#76445b',false]].forEach(([s,color,dashed])=>{const d=s.map((v,i)=>`${i?'L':'M'}${x(i)},${y(v)}`).join(' ');svg+=`<path class="line" d="${d}" stroke="${color}" ${dashed?'stroke-dasharray="5 5" stroke-width="1.5"':''}/>`;s.forEach((v,i)=>svg+=`<circle cx="${x(i)}" cy="${y(v)}" r="3" fill="${color}"><title>${labels[i]} · ${m(v)}</title></circle>`);});labels.forEach((v,i)=>svg+=`<text x="${x(i)}" y="${H-10}" text-anchor="middle">${v}</text>`);return `<div class="legend"><span><i style="background:#76445b"></i>${t('当月','Month')}</span><span><i style="background:#c8a2b3"></i>${t('上月可比','Prior period')}</span><span><i style="background:#c7bba8"></i>${t('去年同期','Prior year')}</span></div><div class="chart-wrap">${svg}</svg></div>`;}
  function barChart(){const p=currentPeriod(),weeks=Math.ceil(p.cap/7),series=ids().map((id,si)=>({id,color:si?'#bca58b':'#8b5b70',values:Array.from({length:weeks},(_,i)=>F.db.sales.filter(s=>s.status==='posted'&&s.store===id&&F.inPeriod(s.date,p)&&Math.floor((Number(s.date.slice(8))-1)/7)===i).reduce((n,s)=>n+s.amount,0))})),W=390,H=235,max=Math.max(...series.flatMap(s=>s.values),100),plot=300/Math.max(weeks,1);let svg=`<svg class="chart-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="${t('按月内每七天分组的门店销售对比','Store comparison by seven-day groups in the month')}">`;for(let j=0;j<4;j++){let y=195-j*53;svg+=`<line class="grid" x1="40" x2="375" y1="${y}" y2="${y}"/><text x="30" y="${y+4}" text-anchor="end">${Math.round(max*j/3/100000)}k</text>`;}for(let i=0;i<weeks;i++){const cx=52+i*plot+plot/2;series.forEach((s,si)=>{const h=s.values[i]/max*159,w=series.length===1?20:15,xx=cx-(series.length*20)/2+si*22;svg+=`<rect x="${xx}" y="${195-h}" width="${w}" height="${h}" rx="4" fill="${s.color}"><title>${e(storeLabel(s.id))} · ${i*7+1}—${Math.min(i*7+7,p.cap)} · ${m(s.values[i])}</title></rect>`;});svg+=`<text x="${cx}" y="220" text-anchor="middle">${i*7+1}–${Math.min(i*7+7,p.cap)}</text>`;}return `<div class="legend">${series.map(s=>`<span><i style="background:${s.color}"></i>${e(name(F.store(F.db,s.id)))}</span>`).join('')}</div><div class="chart-wrap">${svg}</svg></div>`;}
  function ranks(limit=5,by='qty'){const p=currentPeriod(),year=F.periods(state.month).year;return F.db.products.map(product=>{const lines=F.db.sales.filter(s=>s.status==='posted'&&ids().includes(s.store)&&F.inPeriod(s.date,p)).flatMap(s=>s.lines).filter(l=>l.sku===product.sku);const qty=lines.reduce((n,l)=>n+l.qty,0),amount=lines.reduce((n,l)=>n+l.revenue,0),prior=F.saleRevenue(F.db,product.sku,ids(),d=>F.inPeriod(d,year));return {product,qty,amount,growth:F.growth(amount,prior)};}).filter(r=>r.qty).sort((a,b)=>(by==='qty'?b.qty-a.qty:b.amount-a.amount)||a.product.sku.localeCompare(b.product.sku)).slice(0,limit);}
